css:
/* Frappe wraps custom HTML in .print-format (0.75in padding, max-width 8.3in). Override it first. */
@media screen {
	.print-format {
		padding: 0 !important;
		margin: 0 !important;
		max-width: none !important;
		width: 100% !important;
		min-height: 11.69in !important;
		height: 11.69in !important;
		border-radius: 0 !important;
		box-shadow: none !important;
		box-sizing: border-box !important;
		display: flex !important;
		flex-direction: column !important;
	}
}
@media print {
	.print-format {
		padding: 0 !important;
		margin: 0 !important;
		max-width: none !important;
		width: 100% !important;
		min-height: 287mm !important;
		box-sizing: border-box !important;
		display: flex !important;
		flex-direction: column !important;
	}
}
.print-format .fk-sheet {
	flex: 1 1 auto;
	width: 100%;
	min-height: 100%;
	box-sizing: border-box;
	border: 1px solid #e5e7eb;
	border-radius: 10px;
	padding: 14mm 16mm;
	display: flex;
	flex-direction: column;
	justify-content: space-between;
	font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
	color: #111827;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}
.print-format .fk-header { flex: 0 0 auto; }
.print-format .fk-body {
	flex: 1 1 auto;
	display: flex;
	flex-direction: column;
	justify-content: space-between;
	min-height: 120mm;
}
.print-format .fk-block { flex: 0 0 auto; }
.print-format .fk-grow { flex: 1 1 auto; min-height: 10mm; }
.print-format .fk-footer { flex: 0 0 auto; }
.print-format .fk-title { font-size: 28pt; font-weight: 800; margin: 0 0 4pt; line-height: 1.1; }
.print-format .fk-subtitle { font-size: 13pt; color: #6b7280; margin: 0 0 14pt; }
.print-format .fk-section-label { font-size: 9pt; font-weight: 700; letter-spacing: 0.08em; color: #9ca3af; margin: 0 0 8pt; text-transform: uppercase; }
.print-format .fk-row { display: flex; justify-content: space-between; align-items: center; padding: 9pt 0; border-bottom: 1px solid #f3f4f6; font-size: 13pt; line-height: 1.2; }
.print-format .fk-total-row { display: flex; justify-content: space-between; align-items: center; padding: 11pt 0 10pt; font-size: 14pt; font-weight: 800; border-bottom: 1px solid #e5e7eb; margin-bottom: 14pt; }
.print-format .fk-margin-row { margin: 12pt 0 8pt; padding: 10pt 12pt; border-radius: 10px; background: #eef0ff; display: flex; justify-content: space-between; align-items: center; }
.print-format .fk-margin-label { font-size: 13pt; font-weight: 700; color: #4f46e5; }
.print-format .fk-margin-value { display: inline-block; background: #fff; border: 1px solid #d1d5db; border-radius: 8px; padding: 4pt 10pt; font-size: 13pt; font-weight: 700; min-width: 36pt; text-align: center; }
.print-format .fk-tender-row { margin-top: 10pt; padding: 12pt 14pt; border-radius: 10px; background: #e9f6dd; display: flex; justify-content: space-between; align-items: center; }
.print-format .fk-tender-label { font-size: 22pt; font-weight: 900; color: #2f6d21; line-height: 1; }
.print-format .fk-tender-value { font-size: 24pt; font-weight: 900; color: #2f6d21; line-height: 1; }
.print-format .fk-per-kitchen { display: flex; justify-content: space-between; padding-top: 8pt; font-size: 12pt; color: #6b7280; }
